:root{--bg:#0c0c0c;--surface:#1a1a2e;--border:#333;--accent:#00ff41;--accent2:#00e5ff;--accent3:#ff6b35;--accent4:#f5f500;--accent5:#ff00ff;--text:#00ff41;--text2:#00cc33;--text3:#008f11;--glow:0 0 5px rgba(0,255,65,.5),0 0 10px rgba(0,255,65,.3);--crt:linear-gradient(transparent 50%,rgba(0,0,0,.03) 50%);--scanline:repeating-linear-gradient(0deg,transparent,transparent 2px,rgba(0,0,0,.08) 2px,rgba(0,0,0,.08) 4px)}
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:'VT323',monospace;background:var(--bg);color:var(--text);line-height:1.4;background-image:var(--scanline);image-rendering:pixelated}
::selection{background:var(--accent);color:var(--bg)}
.crt{position:relative;overflow:hidden;min-height:100vh}
.crt::before{content:'';position:fixed;top:0;left:0;right:0;bottom:0;background:var(--crt);pointer-events:none;z-index:9999}
.crt::after{content:'';position:fixed;top:0;left:0;right:0;bottom:0;background:radial-gradient(ellipse at center,transparent 60%,rgba(0,0,0,.4) 100%);pointer-events:none;z-index:9998}
.title-bar{background:linear-gradient(90deg,#000080,#1084d0);border-bottom:2px solid #fff;padding:4px 8px;display:flex;align-items:center;justify-content:space-between;font-family:'Press Start 2P',monospace;font-size:10px;color:#fff}
.title-bar .btn-group{display:flex;gap:2px}
.title-bar .win-btn{width:16px;height:14px;background:#c0c0c0;border:1px outset #fff;display:flex;align-items:center;justify-content:center;font-size:8px;color:#000;cursor:pointer;font-family:'VT323',monospace}
.title-bar .win-btn:hover{background:#dfdfdf}
.title-bar .win-btn:active{border-style:inset}
.menu-bar{background:#c0c0c0;border-bottom:2px solid #808080;padding:2px 4px;display:flex;gap:0;font-size:13px;color:#000}
.menu-item{padding:2px 8px;cursor:pointer;font-family:'VT323',monospace}
.menu-item:hover{background:#000080;color:#fff}
.menu-sep{border-left:1px solid #808080;border-right:1px solid #fff;margin:0 2px}
.hero{background:linear-gradient(180deg,#000 0%,#0a0a1a 100%);padding:30px 20px;text-align:center;border-bottom:3px solid var(--accent)}
.hero h1{font-family:'Press Start 2P',monospace;font-size:clamp(10px,2.5vw,18px);color:var(--accent);text-shadow:var(--glow);margin-bottom:12px;letter-spacing:2px}
.hero p{color:var(--text2);font-size:18px;max-width:700px;margin:0 auto 20px}
.stats-row{display:flex;justify-content:center;gap:12px;flex-wrap:wrap}
.stat-box{background:var(--surface);border:2px solid var(--accent);padding:12px 18px;min-width:140px;position:relative}
.stat-box::before{content:'┌';position:absolute;top:-8px;left:4px;color:var(--accent);font-size:10px}
.stat-box::after{content:'┘';position:absolute;bottom:-8px;right:4px;color:var(--accent);font-size:10px}
.stat-num{font-family:'Press Start 2P',monospace;font-size:16px;color:var(--accent);text-shadow:var(--glow)}
.stat-label{color:var(--text3);font-size:14px;margin-top:4px}
.nav-bar{background:#000;border:2px solid var(--accent);margin:0 8px;padding:4px;display:flex;flex-wrap:wrap;gap:2px;position:sticky;top:0;z-index:100}
.nav-btn{flex-shrink:0;padding:4px 10px;background:transparent;border:1px solid var(--text3);color:var(--text2);font-family:'VT323',monospace;font-size:14px;cursor:pointer}
.nav-btn:hover,.nav-btn.active{background:var(--accent);color:#000;border-color:var(--accent)}
.section{max-width:1400px;margin:0 auto;padding:20px 12px}
.section-header{display:flex;align-items:center;gap:10px;margin-bottom:16px;border:1px solid var(--accent);padding:8px 12px;background:rgba(0,255,65,.05)}
.section-icon{font-family:'Press Start 2P',monospace;font-size:10px;color:var(--accent);text-shadow:var(--glow)}
.section-title{font-family:'Press Start 2P',monospace;font-size:12px;color:var(--accent);text-shadow:var(--glow)}
.section-desc{color:var(--text2);font-size:14px;margin-top:4px}
.card-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:8px}
.card{background:var(--surface);border:1px solid var(--border);padding:10px;transition:all .15s;position:relative}
.card:hover{border-color:var(--accent);box-shadow:0 0 8px rgba(0,255,65,.2)}
.card:hover::before{content:'>';position:absolute;left:4px;top:50%;transform:translateY(-50%);color:var(--accent);animation:blink .6s step-end infinite;font-size:10px}
@keyframes blink{0%,100%{opacity:1}50%{opacity:0}}
.card-head{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:6px}
.card-name{font-size:15px;color:var(--accent);word-break:break-all}
.card-name a{color:inherit;text-decoration:none}
.card-name a:hover{text-decoration:underline}
.card-badge{flex-shrink:0;padding:1px 6px;font-size:11px;border:1px solid var(--accent);color:var(--accent);font-family:'Press Start 2P',monospace}
.card-desc{color:var(--text2);font-size:14px;line-height:1.4}
.card-meta{display:flex;gap:10px;margin-top:8px;font-size:12px;color:var(--text3)}
.card-tags{display:flex;gap:4px;flex-wrap:wrap;margin-top:8px}
.tag{padding:1px 5px;font-size:11px;border:1px dashed var(--text3);color:var(--text3)}
.platform-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:10px;margin-bottom:24px}
.platform-card{background:var(--surface);border:2px solid var(--border);padding:14px;text-decoration:none;color:inherit;display:block;transition:all .15s}
.platform-card:hover{border-color:var(--accent);box-shadow:0 0 10px rgba(0,255,65,.2)}
.platform-card h3{font-family:'Press Start 2P',monospace;font-size:10px;color:var(--accent);margin-bottom:8px;text-shadow:var(--glow)}
.platform-card p{color:var(--text2);font-size:14px;margin-bottom:10px}
.platform-card .meta-row{display:flex;gap:6px;font-size:12px;color:var(--text3);flex-wrap:wrap}
.platform-card .meta-row span{background:rgba(0,255,65,.1);padding:2px 6px;border:1px solid var(--text3)}
.cat-tabs{display:flex;gap:3px;flex-wrap:wrap;margin-bottom:14px}
.cat-tab{padding:3px 10px;border:1px solid var(--text3);background:transparent;color:var(--text2);font-family:'VT323',monospace;font-size:14px;cursor:pointer}
.cat-tab:hover,.cat-tab.active{background:var(--accent);color:#000;border-color:var(--accent)}
.search-box{position:relative;max-width:400px;margin-bottom:16px}
.search-box input{width:100%;padding:6px 10px 6px 50px;background:#000;border:2px solid var(--accent);color:var(--accent);font-family:'VT323',monospace;font-size:16px;outline:0}
.search-box input:focus{box-shadow:var(--glow)}
.search-box::before{content:'C:\> ';position:absolute;left:8px;top:50%;transform:translateY(-50%);color:var(--accent);font-size:14px}
.footer{text-align:center;padding:20px;color:var(--text3);font-size:13px;border-top:2px solid var(--accent);margin-top:30px}
.footer a{color:var(--accent);text-decoration:none}
.footer a:hover{text-decoration:underline}
.c-purple{color:var(--accent5);border-color:var(--accent5)}
.c-cyan{color:var(--accent2);border-color:var(--accent2)}
.c-amber{color:var(--accent3);border-color:var(--accent3)}
.c-yellow{color:var(--accent4);border-color:var(--accent4)}
::-webkit-scrollbar{width:12px}
::-webkit-scrollbar-track{background:#1a1a2e}
::-webkit-scrollbar-thumb{background:var(--accent);border:2px solid #1a1a2e}
@media(max-width:768px){.card-grid{grid-template-columns:1fr}.stats-row{gap:6px}.stat-box{min-width:100px;padding:8px 12px}.stat-num{font-size:12px}}

